{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.zouk_db_Blinkit_ads_Fact_items AS WITH blinkit_ads AS ( SELECT COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', TRIM(Date)), SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(Date)), SAFE.PARSE_DATE(\'%d/%m/%Y\', TRIM(Date)) ) AS Date, SAFE_CAST(REPLACE(Estimated_Budget_Consumed, \',\', \'\') AS FLOAT64) AS Estimated_Budget_Consumed, SAFE_CAST(REPLACE(Total_RoAS, \',\', \'\') AS FLOAT64) AS Total_RoAS, SAFE_CAST(REPLACE(CPM, \',\', \'\') AS FLOAT64) AS CPM, SAFE_CAST(REPLACE(Direct_ATC, \',\', \'\') AS FLOAT64) AS Direct_ATC, SAFE_CAST(REPLACE(Direct_Quantities_Sold, \',\', \'\') AS FLOAT64) AS Direct_Quantities_Sold, SAFE_CAST(REPLACE(Direct_Sales, \',\', \'\') AS FLOAT64) AS Direct_Sales, SAFE_CAST(REPLACE(Impressions, \',\', \'\') AS FLOAT64) AS Impressions, ba.Campaign_Name, km.collection AS collection, NULL AS CTR, NULL AS Reach, CAST(NULL AS STRING) AS Match_Type, CAST(NULL AS INT64) AS Unique_Clicks, CAST(NULL AS STRING) AS Targeting_Type, CAST(NULL AS STRING) AS Targeting_Value, \'regular\' AS Type FROM MapleMonk.zouk_db_Blinkit_Ads ba LEFT JOIN ( SELECT Campaign_Name, collection FROM ( SELECT ba.Campaign_Name, km.collection, ROW_NUMBER() OVER ( PARTITION BY LOWER(ba.Campaign_Name) ORDER BY LENGTH(km.keyword) DESC ) AS rn FROM MapleMonk.zouk_db_Blinkit_Ads ba LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(ba.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') ) WHERE rn = 1 ) km ON LOWER(ba.Campaign_Name) = LOWER(km.Campaign_Name) ) , Banner_Ads AS ( SELECT COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', TRIM(Date)), SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(Date)), SAFE.PARSE_DATE(\'%d/%m/%Y\', TRIM(Date)) ) AS Date, SAFE_CAST(REPLACE(Estimated_Budget_Consumed, \',\', \'\') AS FLOAT64) AS Estimated_Budget_Consumed, NULL AS Total_RoAS, SAFE_CAST(REPLACE(CPM, \',\', \'\') AS FLOAT64) AS CPM, NULL AS Direct_ATC, NULL AS Direct_Quantities_Sold, NULL AS Direct_Sales, SAFE_CAST(REPLACE(Impressions, \',\', \'\') AS FLOAT64) AS Impressions, b.Campaign_Name, km.collection AS collection, SAFE_CAST(REPLACE(CTR, \',\', \'\') AS FLOAT64) AS CTR, SAFE_CAST(REPLACE(Reach, \',\', \'\') AS FLOAT64) AS Reach, SAFE_CAST(REPLACE(Match_Type, \',\',\'\' )AS STRING) AS Match_Type, SAFE_CAST(REPLACE(Unique_Clicks, \',\', \'\') AS INT64) AS Unique_Clicks, Targeting_Type, Targeting_Value, \'banner\' AS Type FROM `MapleMonk.Zouk_Blinkit_Banner_Ads` b LEFT JOIN ( SELECT Campaign_Name, collection FROM ( SELECT b.Campaign_Name, km.collection, ROW_NUMBER() OVER ( PARTITION BY LOWER(b.Campaign_Name) ORDER BY LENGTH(km.keyword) DESC ) AS rn FROM MapleMonk.Zouk_Blinkit_Banner_Ads b LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(b.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') ) WHERE rn = 1 ) km ON LOWER(b.Campaign_Name) = LOWER(km.Campaign_Name) ) SELECT Date, Estimated_Budget_Consumed, Total_RoAS, CPM, Direct_ATC, Direct_Quantities_Sold, Direct_Sales, Impressions, Campaign_Name, collection, CTR, Reach, Match_Type, Unique_Clicks, Targeting_Type, Targeting_Value, Type FROM blinkit_ads UNION ALL SELECT Date, Estimated_Budget_Consumed, Total_RoAS, CPM, Direct_ATC, Direct_Quantities_Sold, Direct_Sales, Impressions, Campaign_Name, collection, CTR, Reach, Match_Type, Unique_Clicks, Targeting_Type, Targeting_Value, Type FROM Banner_Ads;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            